import axios, { AxiosError, AxiosResponse } from 'axios';

const http = axios.create({
  // axios configuration
});

const handleError = (error: AxiosError) => {
  // existing error handling logic
};

const handleResponse = (response: AxiosResponse) => {
  // existing response handling logic
};

export interface RetryOptions {
  /**
   * Number of retries after the first attempt. Total attempts = maxRetries + 1.
   * Default: 3
   */
  maxRetries?: number;
  /**
   * Initial delay in milliseconds before the first retry.
   * Default: 250
   */
  initialDelayMs?: number;
  /**
   * Exponential factor for each subsequent retry.
   * Default: 2
   */
  factor?: number;
  /**
   * Whether to add jitter to the delay. If true, uses full jitter strategy
   * (random between 0 and current backoff delay).
   * Default: true
   */
  jitter?: boolean;
  /**
   * Optional maximum cap for delay.
   */
  maxDelayMs?: number;
  /**
   * Custom predicate to decide if we should retry.
   * Receives the result (if any) and the error (if any) from the attempt.
   * Return true to retry, false to stop retrying.
   * Default behavior:
   *   - Retry on any thrown error
   *   - Retry when result has a numeric status >= 400
   */
  shouldRetry?: (result: any | undefined, error: unknown | null, attempt: number) => boolean;
  /**
   * Optional AbortSignal to cancel retries.
   */
  signal?: AbortSignal | null;
  /**
   * Optional hook invoked before a retry delay.
   * Can be async. Exceptions thrown here will abort the retry process.
   */
  onRetry?: (info: {
    attempt: number; // the current attempt number that just failed (1-based)
    delayMs: number;
    error?: unknown;
  }) => void;
}

/**
 * Retries the provided async function up to `maxRetries` total attempts with exponential backoff.
 *
 * Behavior:
 * - Any thrown error from `fn` is considered retryable.
 * - If `fn` resolves to a value that looks like an HTTP response (has a numeric `status`),
 *   any non-2xx status is treated as an error and is retryable (this includes 4xx responses).
 *
 * Defaults: maxRetries = 3 (total attempts), initialDelayMs = 250, factor = 2, jitter = true.
 *
 * @param fn - function that returns a Promise of T
 * @param opts - retry options
 */
export async function retryWithBackoff<T>(
  fn: () => Promise<T>,
  opts?: RetryOptions
): Promise<T> {
  const {
    maxRetries = 3,
    initialDelayMs = 250,
    factor = 2,
    jitter = true,
    onRetry,
    shouldRetry = (result, error, attempt) => {
      if (error) return true;
      if (result && typeof result === "object" && typeof (result as any).status === "number") {
        const status = (result as any).status;
        return status < 200 || status >= 300;
      }
      return false;
    },
    signal,
  } = opts || {};

  if (maxRetries <= 0) {
    throw new Error("maxRetries must be >= 1");
  }

  let lastErr: any = null;

  for (let attempt = 1; attempt <= maxRetries + 1; attempt++) {
    if (signal && signal.aborted) {
      throw new Error("Retry cancelled due to AbortSignal");
    }

    try {
      const result = await fn();

      if (shouldRetry(result, null, attempt)) {
        throw new Error(`Retryable result: ${JSON.stringify(result)}`);
      }

      // Success
      return result;
    } catch (err) {
      lastErr = err;

      // If this was the last attempt, rethrow the error.
      if (attempt >= maxRetries + 1) {
        throw lastErr;
      }

      // Calculate delay
      let delayMs = initialDelayMs * Math.pow(factor, attempt - 1);
      if (jitter) {
        delayMs = Math.random() * delayMs;
      }
      if (opts?.maxDelayMs) {
        delayMs = Math.min(delayMs, opts.maxDelayMs);
      }

      // Call onRetry hook if provided.
      if (onRetry) {
        await onRetry({ attempt, delayMs, error: lastErr });
      }

      // Wait for the calculated delay before the next attempt.
      await new Promise((resolve, reject) => {
        const timeoutId = setTimeout(() => {
          resolve();
        }, delayMs);

        if (signal) {
          signal.addEventListener('abort', () => {
            clearTimeout(timeoutId);
            reject(new Error("Retry cancelled due to AbortSignal"));
          });
        }
      });
    }
  }

  // This line should never be reached due to the throw in the loop.
  throw new Error("Unreachable");
}

export const fetchData = async (url: string, opts?: RetryOptions) => {
  try {
    const response = await retryWithBackoff(() => http.get(url), opts);
    return handleResponse(response);
  } catch (error) {
    return handleError(error);
  }
};
